import{_ as t,o,c as a,ae as r}from"./chunks/framework.BmsPYn1i.js";const _=JSON.parse('{"title":"複雑な物理シミュレーション","description":"","frontmatter":{},"headers":[],"relativePath":"FeaturesIntroduction/Joint/index.md","filePath":"FeaturesIntroduction/Joint/index.md"}'),i={name:"FeaturesIntroduction/Joint/index.md"};function n(s,e,c,d,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="複雑な物理シミュレーション" tabindex="-1">複雑な物理シミュレーション <a class="header-anchor" href="#複雑な物理シミュレーション" aria-label="Permalink to &quot;複雑な物理シミュレーション&quot;">​</a></h1><h2 id="motionの仕組みの利用-推奨" tabindex="-1">Motionの仕組みの利用（推奨） <a class="header-anchor" href="#motionの仕組みの利用-推奨" aria-label="Permalink to &quot;Motionの仕組みの利用（推奨）&quot;">​</a></h2><p>物理エンジン(Rapier)には、剛体同士を「関節」でつなぐJoint （RevoluteJoint・PrismaticJointなど）の機能があり、これを使うと 台車・振り子・ラグドールのような、複数の剛体が連動する複雑な シミュレーションが作れます。</p><p>a3jsでこうした複雑な物理演算を使いたい場合は、 <a href="./../ActionObject/">ActionObject</a>の<strong>Motionの仕組みを使う方法を 推奨</strong>します。Motionは<code>addOneselfToPhysics()</code>/ <code>removeOneselfFromPhysics()</code>というメソッドを持っていて、 シーンへの追加・削除に合わせて複数のRigidBody・Collider・Jointを 物理ワールドへまとめて登録・解除できます。つまり「Jointでつながった 剛体の集まり」を1つのアクションとしてオブジェクトに閉じ込められる ということです。</p><p>実装例はリポジトリの<code>test/test32.js</code>（プリミティブだけでJointを 使った台車を作る例）と<code>test/test33.js</code>（Acerola3Dの3Dモデルと 組み合わせた例）を参照してください。Rapierを直接操作するので、 <a href="https://rapier.rs/docs/user_guides/javascript/joints" target="_blank" rel="noreferrer">RapierのJavaScriptユーザーガイド</a> の知識が必要です。</p><p>なお、<a href="./../OtherFunctions/CarControl.html">CarControlクラス</a>も内部では この仕組み（車体のTransformerとタイヤのMotion）で実装されています。</p><h2 id="将来の予定" tabindex="-1">将来の予定 <a class="header-anchor" href="#将来の予定" aria-label="Permalink to &quot;将来の予定&quot;">​</a></h2><p>現状の方法はRapierのAPIを直接使う必要があり、なかなか大変です。 将来は各種Jointを適用したシミュレーションをもっと簡単に作れる 方法を準備中です。</p>',8)])])}const u=t(i,[["render",n]]);export{_ as __pageData,u as default};
